const pages = document.querySelectorAll('.page');
const names = {'dev-home':'My Work',dashboard:'Delivery Overview',copilot:'AI Copilot Chat',risk:'PR Risk & Impact','ci-failures':'Pipeline Remediation',knowledge:'Knowledge Discovery',ingest:'Contribute Knowledge',incidents:'Delivery & Jira',sme:'Top Contributors',security:'Security & Trust'};
function go(id){pages.forEach(p=>p.classList.toggle('show',p.id===id));document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));document.querySelector('#page-name').textContent=names[id];document.querySelector('.sidebar').classList.remove('open');window.scrollTo(0,0)}
