const menuButton=document.querySelector('#menu');
function setSidebarCollapsed(collapsed){document.body.classList.toggle('sidebar-collapsed',collapsed);menuButton.setAttribute('aria-expanded',String(!collapsed));menuButton.setAttribute('aria-label',collapsed?'Expand navigation':'Collapse navigation');try{localStorage.setItem('buildpulse-sidebar-collapsed',String(collapsed))}catch(error){console.info('Sidebar preference not persisted',error)}}
menuButton.addEventListener('click',()=>{if(window.matchMedia('(max-width: 850px)').matches){document.querySelector('.sidebar').classList.toggle('open')}else{setSidebarCollapsed(!document.body.classList.contains('sidebar-collapsed'))}});
try{setSidebarCollapsed(localStorage.getItem('buildpulse-sidebar-collapsed')==='true')}catch(error){setSidebarCollapsed(false)}
let activeWorkspace='developer';
function setWorkspace(workspace,navigate=true){activeWorkspace=workspace;document.body.dataset.workspace=workspace;document.querySelectorAll('[data-workspace-switch]').forEach(button=>button.classList.toggle('active',button.dataset.workspaceSwitch===workspace));document.querySelectorAll('[data-workspace]').forEach(element=>{const hidden=element.dataset.workspace!==workspace;element.hidden=hidden;element.style.display=hidden?'none':''});const profile=document.querySelector('.user span');if(profile)profile.innerHTML=workspace==='developer'?'Asha Rao<br><small>Software Engineer</small>':'Asha Rao<br><small>Engineering Lead</small>';try{localStorage.setItem('buildpulse-workspace',workspace)}catch(error){console.info('Workspace preference not persisted',error)}if(navigate)go(workspace==='developer'?'dev-home':'dashboard')}
