const input=document.querySelector('#question'), thread=document.querySelector('#thread');
const chatHistory=[];
let activeServiceId=null;
let pendingCopilotContext=null;
const safeText=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
function addMessage(kind, content){thread.insertAdjacentHTML('beforeend',`<div class="message ${kind==='user'?'user-msg':''}">${kind==='user'?'': '<b class="bot">✦</b>'}<div><p>${content}</p></div></div>`)}
async function answer(){
  const q=input.value.trim();if(!q)return;
  addMessage('user',safeText(q));input.value='';
  const pending=document.createElement('div');pending.className='message';
  pending.innerHTML='<b class="bot">✦</b><div><p>BuildPulse is understanding your request and retrieving relevant internal evidence…</p></div>';
  thread.appendChild(pending);thread.scrollIntoView({behavior:'smooth',block:'end'});
  try{
    const requestContext=pendingCopilotContext;pendingCopilotContext=null;
    const response=await fetch('/api/copilot/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,service_id:activeServiceId,history:chatHistory.slice(-10),context:requestContext})});
    if(!response.ok)throw new Error(`API ${response.status}`);
    const result=await response.json();
    if(Object.prototype.hasOwnProperty.call(result,'service_id'))activeServiceId=result.service_id;
    chatHistory.push({role:'user',content:q},{role:'assistant',content:result.answer});
    if(chatHistory.length>12)chatHistory.splice(0,chatHistory.length-12);
    const sources=(result.sources||[]).map(source=>`<div class="source-card"><b>▤ ${safeText(source.title)}</b> ${source.url?`<a href="${safeText(source.url)}" target="_blank" rel="noopener">Open ${safeText(source.source||'source')} ↗</a>`:`${safeText(source.source||'BuildPulse')} evidence`}</div>`).join('');
    const trace=(result.agent_trace||[]).map(event=>safeText(event.agent)).join(' → ');
    const security=result.security?.redacted?`${result.security.findings_count} sensitive item(s) redacted before analysis · `:'Security scan passed · ';
    const origin=responseOrigin(result);
    pending.innerHTML=`<b class="bot">✦</b><div><div class="response-origin ${origin.kind}"><span>${origin.icon}</span><div><strong>${safeText(origin.label)}</strong><small>${safeText(origin.detail)}</small></div></div><p>${safeText(result.answer).replace(/\n/g,'<br>')}</p>${sources?`<details class="evidence-drawer"><summary>${(result.sources||[]).length} evidence source${(result.sources||[]).length===1?'':'s'} used</summary><div class="evidence-list">${sources}</div></details>`:''}<div class="answer-meta"><small>${security}Audit ${safeText(result.audit_id||'not recorded')}</small>${trace?`<small>Agents: ${trace}</small>`:''}</div></div>`;
  }catch(error){pending.innerHTML='<b class="bot">✦</b><div><p><strong>BuildPulse Copilot is temporarily unavailable.</strong> Please retry in a moment.</p><small>The request could not reach the grounded AI service; no fallback answer was generated.</small></div>'}
  thread.scrollIntoView({behavior:'smooth',block:'end'});
}
function responseOrigin(result){
  const provider=String(result.provider_used||'').toLowerCase(),fallback=result.provider_fallback;
  if(fallback)return {kind:'fallback',icon:'!',label:'Fallback response',detail:`The AI provider was unavailable (${fallback}). This answer was generated from stored BuildPulse evidence and deterministic rules.`};
  if(provider==='gemini')return {kind:'ai',icon:'✦',label:'Gemini AI response',detail:'Generated by Gemini using the live context and evidence shown below.'};
  if(provider==='azure_openai')return {kind:'ai',icon:'✦',label:'Azure OpenAI response',detail:'Generated by the configured AI model using live BuildPulse context.'};
  if(provider==='mock')return {kind:'stored',icon:'▤',label:'Stored evidence response',detail:'No external AI model was used. Built from indexed knowledge and deterministic rules.'};
  if(provider==='requirement_intake')return {kind:'system',icon:'?',label:'BuildPulse clarification',detail:'A system-generated clarification; no external AI model was used.'};
  return {kind:'stored',icon:'▤',label:'Local system response',detail:'Generated locally without calling an external AI model.'};
}
document.querySelector('#send').addEventListener('click',answer);input.addEventListener('keydown',e=>{if(e.key==='Enter')answer()});document.querySelectorAll('.suggestions button').forEach(b=>b.addEventListener('click',()=>{input.value=b.textContent;answer()}));
const fileInput=document.querySelector('#fileInput'),fileReady=document.querySelector('#fileReady'),fileName=document.querySelector('#fileName');
fileInput.addEventListener('change',()=>{if(fileInput.files[0]){fileName.textContent=fileInput.files[0].name;fileReady.classList.add('show')}});
document.querySelector('#clearFile').addEventListener('click',()=>{fileInput.value='';fileReady.classList.remove('show')});
document.querySelector('#submitDoc').addEventListener('click',()=>{document.querySelector('#toast').classList.add('show');setTimeout(()=>document.querySelector('#toast').classList.remove('show'),4200)});

// Read-only Repository Intelligence. The static wireframe remains usable if
// FastAPI is unavailable, so the hackathon demo retains a graceful fallback.
const apiBase = '/api';
let repositoryServices = [];
let portfolioOverview = null;
let jiraDashboardData = null;
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
async function apiGet(path){const response=await fetch(`${apiBase}${path}`);if(!response.ok)throw new Error(`API ${response.status}`);return response.json()}
const statusModal=document.querySelector('#system-status-modal'),statusGrid=document.querySelector('#system-status-grid'),statusButton=document.querySelector('#system-status-button');
function statusCard(name,healthy,detail){return `<article class="service-status-card"><span class="service-health ${healthy?'healthy':'unhealthy'}"></span><div><strong>${escapeHtml(name)}</strong><small>${escapeHtml(detail)}</small></div><b class="${healthy?'healthy':'unhealthy'}">${healthy?'Active':'Unavailable'}</b></article>`}
async function loadSystemStatus(){statusGrid.innerHTML='<div class="status-loading">Checking connected services…</div>';statusButton.querySelector('.status-dot').className='status-dot checking';const results=await Promise.allSettled([fetch('/health').then(response=>{if(!response.ok)throw new Error();return response.json()}),apiGet('/agents/status'),apiGet('/jira/status'),apiGet('/knowledge/status'),apiGet('/ci/failures')]);const [healthResult,agentResult,jiraResult,knowledgeResult,githubResult]=results;const health=healthResult.status==='fulfilled'&&healthResult.value.status==='ok',agents=agentResult.status==='fulfilled'?agentResult.value:{},jira=jiraResult.status==='fulfilled'?jiraResult.value:{},knowledge=knowledgeResult.status==='fulfilled'?knowledgeResult.value:{},retrieval=knowledge.retrieval||{};const github=githubResult.status==='fulfilled'&&agents.ci_source==='github',gemini=Boolean(agents.gemini_ready),database=health&&Boolean(retrieval.backend),rag=Boolean(retrieval.vector_search&&retrieval.vector_documents>0);const services=[['Application API',health,health?'FastAPI responding':'Health check failed'],['Jira',Boolean(jira.connected),jira.connected?`${jira.project_key||'Project'} connected`:'Connection unavailable'],['GitHub',github,github?`${githubResult.value.total||0} failed jobs visible`:'Actions source unavailable'],['Gemini',gemini,gemini?'Chat and embeddings connected':'Provider key or model unavailable'],['Database',database,database?`${retrieval.backend} · ${retrieval.indexed_documents||0} documents`:'Database unavailable'],['RAG',rag,rag?`${retrieval.vector_documents||0} vectors · hybrid search`:'Vector retrieval unavailable']];statusGrid.innerHTML=services.map(service=>statusCard(...service)).join('');const allHealthy=services.every(service=>service[1]);statusButton.querySelector('.status-dot').className=`status-dot ${allHealthy?'healthy':'unhealthy'}`;document.querySelector('#system-status-updated').textContent=`Checked ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`}
function openSystemStatus(){statusModal.hidden=false;document.body.style.overflow='hidden';loadSystemStatus()}
function closeSystemStatus(){statusModal.hidden=true;document.body.style.overflow=''}
statusButton.addEventListener('click',openSystemStatus);document.querySelectorAll('[data-close-status]').forEach(button=>button.addEventListener('click',closeSystemStatus));document.querySelector('#refresh-system-status').addEventListener('click',loadSystemStatus);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!statusModal.hidden)closeSystemStatus()});
function initials(name){return name.split(' ').map(part=>part[0]).join('').slice(0,2).toUpperCase()}
function renderOwners(services){const table=document.querySelector('#owner-table');if(!table)return;const rows=services.map(service=>`<div><strong>${escapeHtml(service.name)}<small>${escapeHtml(service.team)}</small></strong><p><b class="avatar">${initials(service.primary_owner)}</b>${escapeHtml(service.primary_owner)}<small>Primary owner</small></p><p><b class="avatar green">${initials(service.backup_owner)}</b>${escapeHtml(service.backup_owner)}<small>Backup owner</small></p><span class="pill green">Covered</span></div>`).join('');table.innerHTML='<div class="tablehead"><span>SYSTEM</span><span>PRIMARY OWNER</span><span>BACKUP OWNER</span><span>STATUS</span></div>'+rows}
function renderPortfolio(overview){portfolioOverview=overview;const card=document.querySelector('#portfolio-card');if(card)card.innerHTML=`<div><small>LIVE REPOSITORY INTELLIGENCE</small><h3>${overview.service_count} services · ${overview.open_change_count} open changes</h3><p>Catalog ownership, dependencies, and branch diffs are being analyzed from the synthetic service repository.</p></div><div class="portfolio-metrics"><div><span>HIGH RISK</span><b>${overview.high_risk_change_count}</b></div><div><span>AWAITING APPROVAL</span><b>${overview.changes_awaiting_approval}</b></div></div>`;renderServicePortfolio()}
function renderServicePortfolio(){const grid=document.querySelector('#service-grid'),summary=document.querySelector('#service-summary');if(!grid||!portfolioOverview)return;const services=portfolioOverview.services||[],issues=jiraDashboardData?.issues||[];const openIssues=issues.filter(issue=>issue.status_category!=='done'),openPrs=pullRequests||[];grid.innerHTML=services.map(service=>{const serviceIssues=openIssues.filter(issue=>issue.service_id===service.id),incidents=serviceIssues.filter(issue=>String(issue.issue_type).toLowerCase().includes('incident')),prs=openPrs.filter(pr=>prService(pr)===service.id),changes=(portfolioOverview.changes||[]).filter(change=>change.service_id===service.id),risk=changes.reduce((highest,change)=>Math.max(highest,change.risk_score||0),0),blockers=serviceIssues.filter(issue=>['Highest','High'].includes(issue.priority)).length,needsAttention=blockers>0||risk>=60;return `<article class="service-card ${needsAttention?'attention':'stable'}"><div class="service-card-head"><div><span class="service-icon">${escapeHtml(initials(service.name))}</span><div><h3>${escapeHtml(service.name)}</h3><p>${escapeHtml(service.team||'Engineering')} · <span class="tier">${escapeHtml(service.tier)} tier</span></p></div></div><span class="health-badge ${needsAttention?'attention':'stable'}"><i class="health-dot ${needsAttention?'attention':'stable'}"></i>${needsAttention?'Needs attention':'Stable'}</span></div><div class="service-kpis"><button data-service-nav="risk" data-service-id="${escapeHtml(service.id)}"><b>${prs.length}</b><span>Open PR${prs.length===1?'':'s'}</span></button><button data-service-nav="open" data-service-id="${escapeHtml(service.id)}"><b>${serviceIssues.length}</b><span>Jira ticket${serviceIssues.length===1?'':'s'}</span></button><button data-service-nav="incidents" data-service-id="${escapeHtml(service.id)}"><b>${incidents.length}</b><span>Incident${incidents.length===1?'':'s'}</span></button><button data-service-nav="risk" data-service-id="${escapeHtml(service.id)}"><b>${risk||'—'}</b><span>Change risk</span></button></div><div class="service-meta"><p><span>Owner</span><strong>${escapeHtml(service.primary_owner)}</strong></p><p><span>Dependencies</span><strong>${service.dependencies?.length?service.dependencies.map(serviceLabel).join(', '):'None'}</strong></p></div><div class="service-card-foot"><span>${blockers} high-priority Jira item${blockers===1?'':'s'}</span><button type="button" data-service-action="${escapeHtml(service.id)}">Ask about owner →</button></div></article>`}).join('')||'<article class="service-card"><p>No catalog services available.</p></article>';const totalIncidents=openIssues.filter(issue=>String(issue.issue_type).toLowerCase().includes('incident')).length;summary.innerHTML=`<button data-summary-nav="contributors"><b>${services.length}</b> service leaders</button><button data-summary-nav="risk"><b>${openPrs.length}</b> open PRs</button><button data-summary-nav="open"><b>${openIssues.length}</b> open Jira tickets</button><button data-summary-nav="incidents"><b>${totalIncidents}</b> active incidents</button>`;grid.querySelectorAll('[data-service-nav]').forEach(button=>button.addEventListener('click',()=>navigateService(button.dataset.serviceNav,button.dataset.serviceId)));grid.querySelectorAll('[data-service-action]').forEach(button=>button.addEventListener('click',()=>navigateService('sme',button.dataset.serviceAction)));summary.querySelectorAll('[data-summary-nav]').forEach(button=>button.addEventListener('click',()=>navigateService(button.dataset.summaryNav,'')))}
function navigateService(destination,serviceId){if(destination==='risk'){const filter=document.querySelector('#risk-service-filter');if(filter)filter.value=serviceId||'';renderPrRows();go('risk');return}if(destination==='sme'){activeServiceId=serviceId||null;input.value=serviceId?`Who owns ${serviceLabel(serviceId)} and who is the backup owner?`:'Who owns this service?';go('copilot');return}if(destination==='contributors'){go('sme');return}const filter=document.querySelector('#jira-service-filter');if(filter)filter.value=serviceId||'';jiraView=destination==='incidents'?'incidents':'open';renderJiraWork();go('incidents')}
let jiraView='open';
function renderJiraWork(){const list=document.querySelector('#jira-work-list'),detail=document.querySelector('#jira-work-detail'),filter=document.querySelector('#jira-service-filter');if(!list||!jiraDashboardData)return;const serviceId=filter?.value||'';const items=(jiraDashboardData.issues||[]).filter(item=>(!serviceId||item.service_id===serviceId)&&(jiraView==='done'?item.status_category==='done':jiraView==='incidents'?item.status_category!=='done'&&String(item.issue_type).toLowerCase().includes('incident'):item.status_category!=='done'));document.querySelector('#jira-open-total').textContent=(jiraDashboardData.issues||[]).filter(item=>item.status_category!=='done').length;document.querySelectorAll('[data-jira-view]').forEach(tab=>tab.classList.toggle('active',tab.dataset.jiraView===jiraView));list.innerHTML=items.map(item=>`<button class="incident jira-item" data-jira-key="${escapeHtml(item.key)}"><span class="pill ${item.priority==='Highest'?'red':item.priority==='High'?'amber':'blue'}">${escapeHtml(item.priority)}</span><h3>${escapeHtml(item.summary)}</h3><p>${escapeHtml(item.key)} · ${escapeHtml(item.service)}</p><b>${escapeHtml(item.status)}</b></button>`).join('')||'<div class="ci-empty"><b>No matching Jira work</b></div>';detail.innerHTML='<div class="ci-empty"><b>Select a Jira ticket</b><p>Ticket details will appear here.</p></div>';list.querySelectorAll('[data-jira-key]').forEach(button=>button.addEventListener('click',()=>{const item=items.find(candidate=>candidate.key===button.dataset.jiraKey);list.querySelectorAll('.jira-item').forEach(row=>row.classList.toggle('selected',row===button));detail.innerHTML=`<div class="cardhead"><div><span class="pill ${item.priority==='Highest'?'red':item.priority==='High'?'amber':'blue'}">${escapeHtml(item.priority)} · ${escapeHtml(item.status)}</span><h2>${escapeHtml(item.summary)}</h2><p>${escapeHtml(item.key)} · ${escapeHtml(item.service)} · ${escapeHtml(item.issue_type)}</p></div><a class="primary" href="${escapeHtml(item.url)}" target="_blank" rel="noopener">Open in Jira ↗</a></div><div class="jira-description"><small>DESCRIPTION</small><p>${escapeHtml(item.description||'No description supplied.')}</p></div>`}))}
function renderSprintOverview(data){const sprint=data.sprint||{},completion=sprint.completion_percent||0;document.querySelector('#sprint-completion').textContent=`${completion}%`;document.querySelector('#sprint-progress-ring').style.background=`conic-gradient(var(--green) 0 ${completion}%,#edf0f5 ${completion}% 100%)`;document.querySelector('#sprint-progress-title').textContent=`${sprint.completed||0} of ${sprint.total||0} stories completed`;document.querySelector('#sprint-progress-note').textContent=sprint.blocked?`${sprint.blocked} release blocker${sprint.blocked===1?'':'s'} require attention.`:'No critical sprint blockers.';document.querySelector('#sprint-total').textContent=sprint.total||0;document.querySelector('#sprint-done').textContent=sprint.completed||0;document.querySelector('#sprint-active').textContent=sprint.in_progress||0;document.querySelector('#sprint-pending').textContent=sprint.pending||0;document.querySelector('#sprint-blocked').textContent=sprint.blocked||0;const board=document.querySelector('#scrum-board-link');if(data.board_url){board.href=data.board_url;board.hidden=false}else{board.hidden=true}}
async function loadServicePortfolio(){try{const [overview,jira,prs]=await Promise.all([apiGet('/portfolio/overview'),apiGet('/jira/dashboard'),apiGet('/pull-requests')]);portfolioOverview=overview;jiraDashboardData=jira;repositoryServices=overview.services||[];pullRequests=prs.items||[];renderServicePortfolio()}catch(error){const grid=document.querySelector('#service-grid');if(grid)grid.innerHTML='<article class="service-card"><p>Service signals are temporarily unavailable.</p></article>'}}
function renderLiveCI(runs){const card=document.querySelector('#live-ci-card');if(!card||!runs.length)return;const run=runs[0];const passed=run.conclusion==='success';card.innerHTML=`<div><small>LIVE GITHUB ACTIONS · ${escapeHtml(run.source)}</small><h3>${escapeHtml(run.workflow)} · ${passed?'Passed':'Needs attention'}</h3><p>${escapeHtml(run.branch||'Unknown branch')} · ${escapeHtml(run.status)} · Latest workflow data collected from GitHub Actions.</p></div><div class="portfolio-metrics"><div><span>RESULT</span><b>${passed?'✓':'!'}</b></div><div><span>RUN ID</span><b>${escapeHtml(run.id)}</b></div></div>`}
function renderFailureIntelligence(analysis){const card=document.querySelector('#ci-failure-card');if(!card)return;const run=analysis.run||{};const source=run.source==='github'?'LIVE GITHUB FAILURE':'DEMO FAILURE FIXTURE';const confidence=analysis.confidence||{};card.innerHTML=`<div><small>${source} · ${escapeHtml(analysis.failure_class||'unknown')}</small><h3>${escapeHtml(run.job||run.workflow||'CI failure')}</h3><p>${escapeHtml(analysis.diagnosis)} <a data-go="copilot">Ask Copilot about the fix →</a></p></div><div class="portfolio-metrics"><div><span>CONFIDENCE</span><b>${escapeHtml(confidence.score||0)}%</b></div><div><span>RISK</span><b>${escapeHtml(analysis.risk?.risk_score||0)}</b></div></div>`;card.querySelectorAll('[data-go]').forEach(element=>element.addEventListener('click',()=>go(element.dataset.go)))}
function renderJiraDashboard(data){const readiness=data.release_readiness??0,incidents=data.open_incidents??0,blockers=data.release_blockers??0;document.querySelector('#jira-readiness').innerHTML=`${escapeHtml(readiness)}<span>%</span>`;document.querySelector('#jira-readiness-note').textContent=`Live from ${data.project_key} · ${blockers} high-priority blockers`;document.querySelector('#jira-readiness-bar').style.width=`${readiness}%`;document.querySelector('#jira-incident-count').textContent=incidents;document.querySelector('#jira-incident-note').innerHTML=`<b class="dot red"></b> ${incidents} open Jira incident${incidents===1?'':'s'}`;document.querySelector('#jira-release-card').innerHTML=`<div class="cardhead"><div><small>LIVE JIRA · ${escapeHtml(data.project_key)}</small><h3>Release readiness</h3></div><span class="pill ${blockers?'amber':'green'}">${blockers?'At risk':'Ready'}</span></div><div class="readiness"><div class="ring"><b>${escapeHtml(readiness)}%</b></div><div><b>${escapeHtml(blockers)} blocker${blockers===1?'':'s'} to resolve</b><p>Calculated from open High and Highest BuildPulse Jira issues.</p><a href="${escapeHtml((data.attention||[])[0]?.url||'#')}" target="_blank" rel="noopener">Open Jira project →</a></div></div>`;document.querySelector('#jira-attention').innerHTML=(data.attention||[]).slice(0,4).map(item=>`<li><b class="dot ${item.priority==='Highest'?'red':'amber'}"></b><div><strong>${escapeHtml(item.summary)}</strong><p>${escapeHtml(item.key)} · ${escapeHtml(item.service)} · ${escapeHtml(item.status)}</p></div><a class="pill ${item.priority==='Highest'?'red':'amber'}" href="${escapeHtml(item.url)}" target="_blank" rel="noopener">${escapeHtml(item.priority)}</a></li>`).join('')||'<li><div><strong>No open BuildPulse Jira issues</strong></div></li>';const counts=data.incidents_by_service||{},max=Math.max(1,...Object.values(counts));document.querySelector('#jira-service-chart').innerHTML=Object.entries({"loan-service":"Loan","payments-api":"Payments","api-gateway":"Gateway","identity-service":"Identity"}).map(([id,label])=>`<div style="height:${Math.max(8,((counts[id]||0)/max)*100)}%"><span>${label}</span></div>`).join('')}
async function loadJiraDashboard(){try{jiraDashboardData=await apiGet('/jira/dashboard');renderJiraDashboard(jiraDashboardData);renderSprintOverview(jiraDashboardData);renderServicePortfolio();renderJiraWork()}catch(error){document.querySelector('#jira-readiness-note').textContent='Jira unavailable · fixture-free mode';document.querySelector('#jira-incident-note').innerHTML='<b class="dot amber"></b> Jira connection unavailable';document.querySelector('#jira-attention').innerHTML='<li><div><strong>Live Jira data unavailable</strong><p>Check Jira configuration and refresh.</p></div></li>'}}
let ciFailures=[];
function serviceLabel(serviceId){const service=repositoryServices.find(item=>item.id===serviceId);return service?.name||serviceId||'Unmapped service'}
function renderCiJobs(){const filter=document.querySelector('#ci-service-filter').value;const jobs=ciFailures.filter(job=>!filter||job.service_id===filter);document.querySelector('#ci-failure-count').textContent=jobs.length;document.querySelector('#ci-failure-source').textContent=jobs.some(job=>job.source==='github')?'Live GitHub Actions':'Demo fixture';const list=document.querySelector('#ci-job-list'),detail=document.querySelector('#ci-job-detail');detail.hidden=true;detail.innerHTML='<div class="ci-empty"><b>Select a failed job</b><p>Diagnosis, fixes, owners, risk, confidence, and evidence will appear here.</p></div>';if(!jobs.length){list.innerHTML='<div class="ci-empty"><b>No failed jobs found</b><p>Try another service or refresh GitHub Actions.</p></div>';return}list.innerHTML=jobs.map(job=>`<button class="ci-job" data-run-id="${escapeHtml(job.id)}"><span class="pill red">Failed</span><strong>${escapeHtml(job.job||job.workflow)}</strong><span>${escapeHtml(serviceLabel(job.service_id))}</span><span>${escapeHtml(job.branch||'Branch unavailable')}</span><small>${job.source==='github'?'LIVE GITHUB':'DEMO FIXTURE'} · ${escapeHtml(job.started_at||'Time unavailable')}</small><b aria-hidden="true">›</b></button>`).join('');list.querySelectorAll('.ci-job').forEach(button=>button.addEventListener('click',()=>selectCiJob(button)))}
async function selectCiJob(button){if(!button)return;document.querySelectorAll('.ci-job').forEach(item=>item.classList.toggle('selected',item===button));const detail=document.querySelector('#ci-job-detail');detail.hidden=false;detail.scrollIntoView({behavior:'smooth',block:'nearest'});detail.innerHTML='<div class="ci-empty">Agent is reading the sanitized log and matching engineering knowledge…</div>';try{const analysis=await apiGet(`/ci/failures/${encodeURIComponent(button.dataset.runId)}/analysis`);const run=analysis.run||{},confidence=analysis.confidence||{},risk=analysis.risk||{},owners=analysis.owners||{};const drivers=(confidence.drivers||[]).map(driver=>`<li><span>${escapeHtml(driver.signal)}</span><b>+${escapeHtml(driver.points)}</b></li>`).join('');const evidence=(analysis.evidence||[]).map(item=>`<details><summary>${escapeHtml(item.title)}</summary><pre>${escapeHtml(item.content||'No excerpt available')}</pre></details>`).join('');const logProof=(analysis.log_evidence||[]).map(line=>`<blockquote>${escapeHtml(line)}</blockquote>`).join('');const documents=(analysis.related_documents||[]).map(item=>`<article class="ci-related-doc"><div><span class="pill ${item.source==='confluence'?'blue':'amber'}">${escapeHtml(item.source)}</span><h4>${escapeHtml(item.title)}</h4><p>${escapeHtml(item.snippet||'')}</p></div>${item.url?`<a class="outline" href="${escapeHtml(item.url)}" target="_blank" rel="noopener">Open ↗</a>`:''}</article>`).join('');const provider=analysis.provider_used==='gemini'?'Gemini agent':analysis.provider_used==='azure_openai'?'Azure OpenAI agent':'Log-analysis fallback';detail.innerHTML=`<div class="ci-detail-head"><div><span class="pill red">${escapeHtml(analysis.failure_class)} failure</span><span class="pill ${analysis.provider_used==='gemini'?'green':'amber'}">${escapeHtml(provider)}</span><h2>${escapeHtml(run.job||run.workflow)}</h2><p>${escapeHtml(serviceLabel(run.service_id))} · ${escapeHtml(run.failed_step||'Failed step unavailable')} · ${run.source==='github'?'Live GitHub':'Demo fixture'}</p></div><div class="ci-score"><b>${escapeHtml(confidence.score||0)}%</b><span>confidence</span></div></div><div class="ci-detail-grid"><section><small>DIAGNOSIS</small><p>${escapeHtml(analysis.diagnosis)}</p><small>ROOT CAUSE</small><p>${escapeHtml(analysis.root_cause)}</p></section><section class="fix"><small>RECOMMENDED FIX</small><p>${escapeHtml(analysis.recommended_fix)}</p></section></div><div class="ci-facts"><div><small>CHANGE RISK</small><b>${escapeHtml(risk.risk_score||0)}/100 · ${escapeHtml(risk.risk_level||'unknown')}</b></div><div><small>PRIMARY OWNER</small><b>${escapeHtml(owners.primary||'Unassigned')}</b></div><div><small>BACKUP OWNER</small><b>${escapeHtml(owners.backup||'Unassigned')}</b></div><div><small>LOG SECURITY</small><b>${analysis.security?.redacted?'Sensitive data redacted':analysis.security?.available?'Scan passed':'Metadata only'}</b></div></div><div class="ci-analysis-lower"><section><h3>Exact log evidence</h3>${logProof||'<p>No bounded error excerpt available.</p>'}<small>${escapeHtml(analysis.confidence_reason||'')}</small></section><section><h3>Verification plan</h3><ol>${(analysis.verification_steps||[]).map(check=>`<li>${escapeHtml(check)}</li>`).join('')}</ol></section></div><div class="ci-related"><h3>Suggested knowledge for this job</h3>${documents||'<p>No matching engineering documents were found.</p>'}</div><div class="ci-evidence"><h3>Raw evidence</h3>${evidence}</div><div class="ci-detail-actions"><button class="primary" id="ci-ask-copilot">✦ Continue with Copilot</button>${run.url?`<a class="outline" href="${escapeHtml(run.url)}" target="_blank" rel="noopener">Open GitHub job ↗</a>`:''}<small>${analysis.provider_fallback?`AI unavailable (${escapeHtml(analysis.provider_fallback)}) · `:''}Audit ${escapeHtml(analysis.audit_id)}</small></div>`;document.querySelector('#ci-ask-copilot').addEventListener('click',()=>{pendingCopilotContext={type:'ci_failure',run_id:String(run.id),service_id:run.service_id,job_name:run.job||run.workflow};activeServiceId=run.service_id||activeServiceId;input.value=`Explain this failed job and give me the safest verified remediation steps.`;go('copilot');answer()})}catch(error){detail.innerHTML='<div class="ci-empty"><b>Analysis unavailable</b><p>The backend could not analyze this failed job.</p></div>'}}
async function loadCiFailures(){const list=document.querySelector('#ci-job-list');list.innerHTML='<div class="ci-empty">Loading failed jobs…</div>';try{const response=await apiGet('/ci/failures');ciFailures=response.items||[];renderCiJobs()}catch(error){list.innerHTML='<div class="ci-empty"><b>Failed jobs unavailable</b><p>Check the API connection and try again.</p></div>'}}
async function renderServiceContext(serviceId){if(!serviceId)return;try{const service=await apiGet(`/services/${encodeURIComponent(serviceId)}`);const card=document.querySelector('#portfolio-card');if(card)card.innerHTML=`<div><small>SELECTED SERVICE · LIVE CATALOG</small><h3>${escapeHtml(service.name)}</h3><p>Primary: ${escapeHtml(service.primary_owner)} · Backup: ${escapeHtml(service.backup_owner)} · Dependencies: ${escapeHtml(service.depends_on.join(', ')||'None')}</p></div><div class="portfolio-metrics"><div><span>TIER</span><b>${escapeHtml(service.tier)}</b></div><div><span>DEPENDED ON BY</span><b>${service.depended_on_by.length}</b></div></div>`}catch(error){console.info('Service context fallback active',error)}}
function renderRisk(risk){document.querySelector('#pr-risk-detail').hidden=false;document.querySelector('#risk-score').textContent=risk.risk_score;const level=document.querySelector('#risk-level');level.textContent=`${risk.risk_level} risk`;level.className=`pill ${risk.risk_level==='high'?'red':risk.risk_level==='medium'?'amber':'green'}`;document.querySelector('#risk-title').textContent=`PR #${risk.pr_number} · ${risk.service}`;const historical=risk.historical_incidents||[],top=historical[0],secret=risk.security?.secret_detected;document.querySelector('#risk-summary').textContent=`${risk.changed_files.length} changed files · Primary owner: ${risk.owners.primary} · Review status: ${risk.owners.review_status}.${secret?' Merge blocked: synthetic secret detected.':''}${top?` Similar resolved incident: ${top.key} (${top.similarity_score}%).`:''}`;const open=document.querySelector('#risk-open-pr');open.href=risk.url||`https://github.com/vickypandeyindia462-code/buildpulse-demo-services/pull/${risk.pr_number}`;document.querySelector('#risk-formula').innerHTML='<small>DETERMINISTIC SCORE</small>'+risk.drivers.slice(-3).map(driver=>`<p>${escapeHtml(driver.factor)} <b>${driver.points>0?'+':''}${driver.points}</b></p>`).join('');document.querySelector('#risk-drivers').innerHTML=risk.drivers.map((driver,index)=>{const incident=historical.find(item=>item.key===driver.jira_issue),security=driver.factor.includes('Secret detected');return `<article class="card ${security?'security-driver':''}"><span class="pill ${security||driver.jira_issue?'red':index===1?'amber':'blue'}">${driver.points>0?'+':''}${driver.points} points</span><h3>${escapeHtml(driver.factor)}</h3><p>${security?`${escapeHtml((driver.finding_types||[]).join(', '))} found in the PR diff. The value is never displayed.`:incident?`${escapeHtml(incident.key)} · ${escapeHtml(incident.similarity_score)}% similar · resolved by ${escapeHtml(incident.resolved_by)}`:driver.dependencies?`Affected dependencies: ${escapeHtml(driver.dependencies.join(', '))}.`:`PR #${risk.pr_number} · ${escapeHtml(risk.service)}`}</p>${incident?`<a href="${escapeHtml(incident.url)}" target="_blank" rel="noopener">Review historical resolution →</a>`:`<a>${escapeHtml(security?risk.recommended_checks[0]:risk.recommended_checks[index]||risk.recommended_checks[0])}</a>`}</article>`}).join('')}
let pullRequests=[];
function prService(pr){const branch=(pr.branch||'').toLowerCase();return branch.includes('payment')?'payments-api':branch.includes('gateway')?'api-gateway':branch.includes('identity')?'identity-service':branch.includes('loan')?'loan-service':''}
function renderPrRows(){const filter=document.querySelector('#risk-service-filter').value,items=pullRequests.filter(pr=>!filter||prService(pr)===filter),list=document.querySelector('#pr-list');document.querySelector('#pr-risk-detail').hidden=true;if(!items.length){list.innerHTML='<div class="ci-empty"><b>No open pull requests found</b></div>';return}list.innerHTML=items.map(pr=>`<button class="ci-job pr-job" data-pr="${pr.number}"><span class="pill blue">Open</span><strong>#${pr.number} · ${escapeHtml(pr.title)}</strong><span>${escapeHtml(serviceLabel(prService(pr)))}</span><span>${escapeHtml(pr.branch)} → ${escapeHtml(pr.base)}</span><small>LIVE GITHUB · ${escapeHtml(pr.updated_at)}</small><b aria-hidden="true">›</b></button>`).join('');list.querySelectorAll('.pr-job').forEach(button=>button.addEventListener('click',async()=>{list.querySelectorAll('.pr-job').forEach(row=>row.classList.toggle('selected',row===button));document.querySelector('#pr-risk-detail').hidden=false;document.querySelector('#risk-title').textContent='Analyzing pull request…';try{renderRisk(await apiGet(`/pull-requests/${button.dataset.pr}/risk`));document.querySelector('#pr-risk-detail').scrollIntoView({behavior:'smooth',block:'nearest'})}catch(error){document.querySelector('#risk-title').textContent='Risk analysis unavailable'}}))}
async function loadPullRequests(){const list=document.querySelector('#pr-list');list.innerHTML='<div class="ci-empty">Loading open GitHub pull requests…</div>';try{const response=await apiGet('/pull-requests');pullRequests=response.items||[];renderPrRows();renderServicePortfolio()}catch(error){list.innerHTML='<div class="ci-empty"><b>Pull requests unavailable</b><p>Check GitHub access and refresh.</p></div>'}}
async function loadKnowledge(){const container=document.querySelector('#knowledge-results'),query=document.querySelector('#knowledge-query').value.trim(),source=document.querySelector('input[name="knowledge-source"]:checked').value;container.innerHTML='<p class="result-count">Searching approved knowledge sources…</p>';try{const response=await apiGet(`/knowledge/search?q=${encodeURIComponent(query)}&source=${encodeURIComponent(source)}`);container.innerHTML=`<p class="result-count">${response.total} results · ${escapeHtml((response.sources||[]).join(' + ')||source)} · sorted by relevance</p>`+(response.items||[]).map(item=>`<article class="result"><span class="docicon ${item.source==='confluence'?'purplebg':''}">${item.source==='confluence'?'◇':'▤'}</span><div><div><span class="pill ${item.source==='confluence'?'blue':'amber'}">${escapeHtml(item.source)}</span></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.snippet||item.content||'')}</p><small><b>${escapeHtml(item.score||0)}% match</b></small></div>${item.url?`<a class="outline" href="${escapeHtml(item.url)}" target="_blank" rel="noopener" aria-label="Open ${escapeHtml(item.title)}">↗</a>`:'<span class="pill">LOCAL</span>'}</article>`).join('')||'<div class="ci-empty"><b>No matching knowledge found</b></div>'}catch(error){container.innerHTML='<div class="ci-empty"><b>Knowledge search unavailable</b><p>Check the API and Confluence connection.</p></div>'}}
async function loadRepositoryIntelligence(){try{const overview=await apiGet('/portfolio/overview');repositoryServices=overview.services;renderPortfolio(overview);const selector=document.querySelector('#dashboard-service-select'),developerSelector=document.querySelector('#developer-service-select'),riskFilter=document.querySelector('#risk-service-filter'),jiraFilter=document.querySelector('#jira-service-filter');repositoryServices.forEach(service=>{const option=`<option value="${escapeHtml(service.id)}">${escapeHtml(service.name)}</option>`;selector.insertAdjacentHTML('beforeend',option);developerSelector.insertAdjacentHTML('beforeend',option);riskFilter.insertAdjacentHTML('beforeend',option);jiraFilter.insertAdjacentHTML('beforeend',option)});const defaultService=repositoryServices[0]?.id||'';[selector,developerSelector,riskFilter,jiraFilter].forEach(filter=>filter.value=defaultService);renderServiceContext(defaultService);renderDeveloperInbox();renderPrRows();renderJiraWork();selector.addEventListener('change',()=>renderServiceContext(selector.value));developerSelector.addEventListener('change',renderDeveloperInbox);jiraFilter.addEventListener('change',renderJiraWork);try{renderLiveCI((await apiGet('/ci/runs')).items||[])}catch(error){console.info('Live CI card unavailable',error)}try{const failures=(await apiGet('/ci/failures')).items||[];if(failures.length)renderFailureIntelligence(await apiGet(`/ci/failures/${encodeURIComponent(failures[0].id)}/analysis`))}catch(error){console.info('CI failure intelligence unavailable',error)}}catch(error){console.info('Repository Intelligence fallback active',error)}}
async function loadCiServiceFilter(){try{const response=await apiGet('/services');const selector=document.querySelector('#ci-service-filter'),services=response.items||[];services.forEach(service=>selector.insertAdjacentHTML('beforeend',`<option value="${escapeHtml(service.id)}">${escapeHtml(service.name)}</option>`));if(services.length){selector.value=services[0].id;if(ciFailures.length)renderCiJobs()}}catch(error){console.info('CI service filter unavailable',error)}}
async function loadProviderStatus(){const badge=document.querySelector('#provider-status');if(!badge)return;try{const status=await apiGet('/agents/status');badge.className=`provider-status ${status.mode==='live'?'live':'demo'}`;badge.querySelector('span').textContent=status.mode==='live'?`${String(status.llm_provider).replaceAll('_',' ')} connected · ${status.available_tools?.length||0} trusted tools`:'Safe demo model · add a provider key for generative answers'}catch(error){badge.querySelector('span').textContent='Model status unavailable';badge.className='provider-status demo'}}
async function loadContributorRecognition(){const grid=document.querySelector('#contributor-grid'),hero=document.querySelector('#recognition-hero');if(!grid||!hero)return;grid.innerHTML='<div class="ci-empty">Calculating recognition from source history…</div>';try{const data=await apiGet('/contributors/recognition'),quality=data.quality_leader,confluence=data.confluence_leader;hero.innerHTML=`<article class="quality"><span class="award-icon">★</span><div><small>CODE QUALITY LEADER</small><h2>${escapeHtml(quality?.name||'Not enough data')}</h2><p>${quality?`${quality.source_commits} source commits · ${quality.test_commits} test contributions · ${quality.score} points`:'No qualifying code history found.'}</p></div></article><article class="knowledge"><span class="award-icon">◇</span><div><small>TOP CONFLUENCE CONTRIBUTOR</small><h2>${escapeHtml(confluence?.name||'Awaiting contribution data')}</h2><p>${confluence?`${confluence.pages} current page${confluence.pages===1?'':'s'} · live Confluence metadata`:'Confluence author metadata is unavailable.'}</p></div></article>`;grid.innerHTML=(data.service_leaders||[]).map((leader,index)=>`<article class="contributor-card"><div class="rank">${index+1}</div><b class="avatar ${index%2?'green':'purple'}">${escapeHtml(initials(leader.name))}</b><div><small>${escapeHtml(leader.service)}</small><h3>${escapeHtml(leader.name)}</h3><p><strong>${leader.commits}</strong> commit${leader.commits===1?'':'s'} touching this service</p></div><span class="award-pill">Top contributor</span></article>`).join('')||'<div class="ci-empty"><b>No service contribution history found</b></div>';document.querySelector('#recognition-period').textContent=`${data.period} · ${String(data.source).toUpperCase()}`;document.querySelector('#recognition-formula').textContent=data.quality_formula}catch(error){grid.innerHTML='<div class="ci-empty"><b>Recognition data unavailable</b><p>Check the repository and Confluence connections, then refresh.</p></div>';hero.innerHTML='<article><small>CONTRIBUTION SIGNALS</small><h2>Source unavailable</h2></article>'}}
let developerSignals={failures:[],prs:[],jira:null,knowledge:[]};
function actionCard(item,index){return `<article class="action-item ${item.tone}" role="button" tabindex="0" data-work-index="${index}"><span class="work-number">${index+1}</span><div class="action-meta"><span class="pill ${item.pill}">${escapeHtml(item.label)}</span><span>${escapeHtml(item.service)}</span></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.description)}</p><footer><small>${escapeHtml(item.evidence)}</small><b>${escapeHtml(item.action)} →</b></footer></article>`}
function openInboxItem(item){if(item.page==='ci-failures'){const filter=document.querySelector('#ci-service-filter');filter.value=item.serviceId||filter.value;renderCiJobs();go('ci-failures');setTimeout(()=>{const row=document.querySelector(`.ci-job[data-run-id="${CSS.escape(String(item.id))}"]`);if(row)selectCiJob(row)},50);return}if(item.page==='incidents'){const filter=document.querySelector('#jira-service-filter');filter.value=item.serviceId||filter.value;jiraView='open';renderJiraWork();go('incidents');setTimeout(()=>document.querySelector(`[data-jira-key="${CSS.escape(String(item.id))}"]`)?.click(),50);return}if(item.page==='risk'){const filter=document.querySelector('#risk-service-filter');filter.value=item.serviceId||filter.value;renderPrRows();go('risk');setTimeout(()=>document.querySelector(`.pr-job[data-pr="${CSS.escape(String(item.id))}"]`)?.click(),50)}}
function renderDeveloperInbox(){const container=document.querySelector('#developer-action-queue');if(!container)return;const filter=document.querySelector('#developer-service-select')?.value||'';const failures=developerSignals.failures.filter(item=>!filter||item.service_id===filter);const prs=developerSignals.prs.filter(item=>!filter||prService(item)===filter);const jiraOpen=(developerSignals.jira?.issues||[]).filter(item=>item.status_category!=='done'&&(!filter||item.service_id===filter));const assigned=jiraOpen.filter(item=>item.assignee);const attention=jiraOpen.filter(item=>!item.assignee&&['Highest','High'].includes(item.priority));const items=[];failures.forEach(job=>items.push({id:job.id,serviceId:job.service_id,tone:'critical',pill:'red',label:'Pipeline failed',service:serviceLabel(job.service_id),title:job.job||job.workflow||'Failed CI job',description:`${job.failed_step||'A required CI step failed'} on ${job.branch||'the current branch'}.`,page:'ci-failures',action:'Investigate',evidence:job.source==='github'?'Live GitHub':'Demo evidence'}));assigned.forEach(issue=>items.push({id:issue.key,serviceId:issue.service_id,tone:issue.priority==='Highest'?'critical':'priority',pill:issue.priority==='Highest'?'red':'amber',label:'Assigned Jira',service:serviceLabel(issue.service_id),title:`${issue.key} · ${issue.summary}`,description:`Assigned to ${issue.assignee} · ${issue.status} · ${issue.priority} priority.`,page:'incidents',action:'Open assigned work',evidence:'Live Jira assignment'}));attention.slice(0,2).forEach(issue=>items.push({id:issue.key,serviceId:issue.service_id,tone:issue.priority==='Highest'?'critical':'priority',pill:issue.priority==='Highest'?'red':'amber',label:`${issue.priority} Jira`,service:serviceLabel(issue.service_id),title:`${issue.key} · ${issue.summary}`,description:`${issue.status} · unassigned release-impacting work.`,page:'incidents',action:'Review blocker',evidence:'Live Jira'}));prs.slice(0,2).forEach(pr=>items.push({id:pr.number,serviceId:prService(pr),tone:'normal',pill:'blue',label:'Open PR',service:serviceLabel(prService(pr)),title:`#${pr.number} · ${pr.title}`,description:`${pr.branch} → ${pr.base}.`,page:'risk',action:'Assess risk',evidence:'Live GitHub'}));const order={critical:0,priority:1,normal:2};items.sort((a,b)=>order[a.tone]-order[b.tone]);const visible=items.slice(0,7);container.innerHTML=visible.length?visible.map(actionCard).join(''):'<div class="ci-empty"><b>No priority work for this service</b><p>No failed pipelines, assigned Jira work, blockers, or open changes were found.</p></div>';container.querySelectorAll('[data-work-index]').forEach(card=>{const open=()=>openInboxItem(visible[Number(card.dataset.workIndex)]);card.addEventListener('click',open);card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}})});document.querySelector('#dev-action-count').textContent=failures.length+assigned.length+attention.length;document.querySelector('#dev-pipeline-health').textContent=failures.length?'Pipeline action required':'Pipelines healthy';document.querySelector('#dev-pipeline-note').textContent=assigned.length?`${assigned.length} assigned Jira item${assigned.length===1?'':'s'}`:failures.length?`${failures.length} failed job${failures.length===1?'':'s'}`:'No assigned Jira work';document.querySelector('#dev-pr-count').textContent=prs.length;document.querySelector('#dev-freshness').textContent=`${visible.length} priority item${visible.length===1?'':'s'} · Updated ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`}
function renderDeveloperKnowledge(items){const grid=document.querySelector('#developer-context-grid');if(!grid)return;grid.innerHTML=(items||[]).slice(0,3).map(item=>`<article><span class="context-type">${escapeHtml((item.source||'knowledge').toUpperCase())}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.snippet||item.content||'Approved engineering guidance')}</p>${item.url?`<a href="${escapeHtml(item.url)}" target="_blank" rel="noopener">Open evidence ↗</a>`:'<a data-go="knowledge">View in Knowledge →</a>'}</article>`).join('')||'<article><span class="context-type">KNOWLEDGE GAP</span><h3>No matching guidance found</h3><p>This is a candidate for a new verified runbook after the issue is resolved.</p><a data-go="ingest">Contribute knowledge →</a></article>';grid.querySelectorAll('[data-go]').forEach(link=>link.addEventListener('click',()=>go(link.dataset.go)))}
async function loadDeveloperWorkspace(){const container=document.querySelector('#developer-action-queue');try{const [failureData,prData,jiraData,knowledgeData]=await Promise.all([apiGet('/ci/failures'),apiGet('/pull-requests'),apiGet('/jira/dashboard'),apiGet('/knowledge/search?q=pipeline%20failure%20remediation%20rollback&source=all')]);developerSignals={failures:failureData.items||[],prs:prData.items||[],jira:jiraData,knowledge:knowledgeData.items||[]};renderDeveloperInbox();renderDeveloperKnowledge(developerSignals.knowledge)}catch(error){container.innerHTML='<div class="ci-empty"><b>Engineering inbox is temporarily unavailable</b><p>One or more live sources could not be reached. Existing workspaces remain available.</p></div>';document.querySelector('#dev-freshness').textContent='Source refresh failed'}}
const plannerStorageKey='buildpulse-developer-planner-v1';
let plannerItems=[];let plannerSelectedDate=new Date().toISOString().slice(0,10);
function loadPlannerItems(){try{plannerItems=JSON.parse(localStorage.getItem(plannerStorageKey)||'[]')}catch(error){plannerItems=[]}}
function savePlannerItems(){try{localStorage.setItem(plannerStorageKey,JSON.stringify(plannerItems))}catch(error){console.info('Planner could not be saved',error)}}
function localDateKey(date){const shifted=new Date(date.getTime()-date.getTimezoneOffset()*60000);return shifted.toISOString().slice(0,10)}
function renderPlanner(){const week=document.querySelector('#planner-week'),list=document.querySelector('#planner-items');if(!week||!list)return;const start=new Date();start.setHours(0,0,0,0);const days=Array.from({length:7},(_,index)=>{const date=new Date(start);date.setDate(start.getDate()+index);return date});week.innerHTML=days.map(date=>{const key=localDateKey(date),count=plannerItems.filter(item=>item.date===key).length;return `<button class="planner-day ${key===plannerSelectedDate?'selected':''}" data-planner-day="${key}"><small>${date.toLocaleDateString([],{weekday:'short'}).toUpperCase()}</small><b>${date.getDate()}</b><span>${count?`${count} item${count===1?'':'s'}`:'Open'}</span></button>`}).join('');week.querySelectorAll('[data-planner-day]').forEach(button=>button.addEventListener('click',()=>{plannerSelectedDate=button.dataset.plannerDay;renderPlanner()}));const selected=plannerItems.filter(item=>item.date===plannerSelectedDate).sort((a,b)=>a.createdAt-b.createdAt);list.innerHTML=selected.length?selected.map(item=>`<article class="planner-item ${item.type} ${item.done?'done':''}"><button class="planner-check" data-planner-toggle="${item.id}" aria-label="Mark complete">${item.done?'✓':''}</button><div><span class="planner-type">${escapeHtml(item.type)}</span><h3>${escapeHtml(item.title)}</h3>${item.notes?`<p>${escapeHtml(item.notes)}</p>`:''}</div><button class="planner-delete" data-planner-delete="${item.id}" aria-label="Delete">×</button></article>`).join(''):`<div class="planner-empty"><b>No plans for ${new Date(`${plannerSelectedDate}T12:00:00`).toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'})}</b><p>Add a task, meeting, declaration, or note.</p></div>`;list.querySelectorAll('[data-planner-toggle]').forEach(button=>button.addEventListener('click',()=>{const item=plannerItems.find(entry=>entry.id===button.dataset.plannerToggle);if(item){item.done=!item.done;savePlannerItems();renderPlanner()}}));list.querySelectorAll('[data-planner-delete]').forEach(button=>button.addEventListener('click',()=>{plannerItems=plannerItems.filter(item=>item.id!==button.dataset.plannerDelete);savePlannerItems();renderPlanner()}))}
const plannerModal=document.querySelector('#planner-modal');
function openPlanner(){document.querySelector('#planner-date').value=plannerSelectedDate;plannerModal.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>document.querySelector('#planner-title').focus(),0)}
function closePlanner(){plannerModal.hidden=true;document.body.style.overflow=''}
document.querySelector('#planner-add-button').addEventListener('click',openPlanner);document.querySelectorAll('[data-close-planner]').forEach(button=>button.addEventListener('click',closePlanner));document.querySelector('#planner-form').addEventListener('submit',event=>{event.preventDefault();const date=document.querySelector('#planner-date').value;plannerItems.push({id:`plan-${Date.now()}`,title:document.querySelector('#planner-title').value.trim(),date,type:document.querySelector('#planner-type').value,notes:document.querySelector('#planner-notes').value.trim(),done:false,createdAt:Date.now()});plannerSelectedDate=date;savePlannerItems();event.target.reset();closePlanner();renderPlanner()});
loadPlannerItems();renderPlanner();
